function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Each value is an integer from -10^5 to 10^5.';
  return null;
}

