function maximumSumScore(nums) {
  let total = 0;
  for (const num of nums) {
    total += num;
  }

  let prefix = 0;
  let best = -Infinity;
  for (let i = 0; i < nums.length; i++) {
    const suffix = total - prefix;
    prefix += nums[i];
    best = Math.max(best, prefix, suffix);
  }
  return best;
}

