function maximumSumScore(nums) {
  const n = nums.length;
  let answer = null;
  for (let i = 0; i < n; i++) {
    let front = 0;
    for (let j = 0; j <= i; j++) front += nums[j];
    let back = 0;
    for (let j = i; j < n; j++) back += nums[j];
    const score = front > back ? front : back;
    if (answer === null || score > answer) answer = score;
  }
  return answer;
}

