function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const style = rand();
  const span = size === 'large' || style < 0.3 ? 100000 : 10;
  // Sometimes lean the values negative so the best score is negative or sits in the middle.
  const shift = style > 0.7 ? -Math.floor(span / 2) : 0;
  const nums = Array.from({ length: n }, () => {
    const v = Math.floor(rand() * (2 * span + 1)) - span + shift;
    return Math.max(-100000, Math.min(100000, v));
  });
  return [nums];
}
